// Advance to the next implementation for this primitive descriptor.
dnnl_status_t st = dnnl_primitive_desc_next_impl(*primitive_desc);
// API contract: success or last_impl_reached are valid outcomes.
if (!(st == dnnl_success || st == dnnl_last_impl_reached)) { FUZZ_BAIL(); }
// Return the (possibly advanced) primitive_desc for continued iteration/usage.

// Clone the provided primitive descriptor. The result must be destroyed later.
dnnl_primitive_desc_t cloned_pd = nullptr;
dnnl_status_t st = dnnl_primitive_desc_clone(&cloned_pd, *existing_primitive_desc);
if (st != dnnl_success || !cloned_pd) { FUZZ_BAIL(); }
// Expose the cloned handle via the output pointer.
dnnl_primitive_desc_t *primitive_desc = &cloned_pd;

// Destroy the primitive descriptor (NULL is allowed as no-op by convention).
(void)dnnl_primitive_desc_destroy(*primitive_desc);
// After this call, primitive_desc must not be used again.

// Exercise several safe query kinds with correctly-typed result storage.
// 1) number of inputs (s32)
int num_inputs = 0;
dnnl_status_t st = dnnl_primitive_desc_query(*primitive_desc, dnnl_query_num_of_inputs_s32, 0, &num_inputs);
if (st != dnnl_success) { FUZZ_BAIL(); }
// 2) number of outputs (s32)
int num_outputs = 0;
st = dnnl_primitive_desc_query(*primitive_desc, dnnl_query_num_of_outputs_s32, 0, &num_outputs);
if (st != dnnl_success) { FUZZ_BAIL(); }
// 3) implementation info string (const char*)
const char *impl = nullptr;
st = dnnl_primitive_desc_query(*primitive_desc, dnnl_query_impl_info_str, 0, &impl);
if (st != dnnl_success) { FUZZ_BAIL(); }
// 4) primitive kind (enum value returned via dnnl_primitive_kind_t*)
dnnl_primitive_kind_t pk = dnnl_undefined_primitive;
st = dnnl_primitive_desc_query(*primitive_desc, dnnl_query_primitive_kind, 0, &pk);
if (st != dnnl_success) { FUZZ_BAIL(); }
// 5) prop kind (enum returned via dnnl_prop_kind_t*)
dnnl_prop_kind_t prop = dnnl_prop_kind_undef;
st = dnnl_primitive_desc_query(*primitive_desc, dnnl_query_prop_kind, 0, &prop);
if (st != dnnl_success) { FUZZ_BAIL(); }
// PD is returned for further use.

// Query a 32-bit integer property; number of inputs is always defined.
int v = dnnl_primitive_desc_query_s32(*primitive_desc, dnnl_query_num_of_inputs_s32, 0);
(void)v; // helper may return 0 for unsupported queries as well; just exercise it.

// Instantiate a primitive from the given primitive descriptor.
dnnl_primitive_t prim_handle = nullptr;
dnnl_status_t st = dnnl_primitive_create(&prim_handle, *primitive_desc);
if (st != dnnl_success || !prim_handle) { FUZZ_BAIL(); }
// Output both primitive and the PD (PD may be reused for further queries).
dnnl_primitive_t *primitive = &prim_handle;

// To obtain a valid cache blob matching the PD, first create a seed primitive.
dnnl_primitive_t seed = nullptr;
dnnl_status_t st = dnnl_primitive_create(&seed, *primitive_desc);
if (st != dnnl_success || !seed) { FUZZ_BAIL(); }
// Query required cache blob size.
size_t blob_size = 0;
st = dnnl_primitive_get_cache_blob(seed, &blob_size, nullptr);
if (st != dnnl_success) { FUZZ_BAIL(); }
// Allocate a bounded buffer for the blob to keep within fuzzer budget.
if (blob_size > 2048) { blob_size = 0; }
std::vector<uint8_t> blob; if (blob_size) { blob.resize(blob_size); }
if (blob_size > 0) {
    size_t cap = blob_size;
    st = dnnl_primitive_get_cache_blob(seed, &cap, blob.data());
    if (st != dnnl_success) { FUZZ_BAIL(); }
}
// Create another primitive from the cache blob for the same PD.
dnnl_primitive_t from_blob = nullptr;
st = dnnl_primitive_create_from_cache_blob(&from_blob, *primitive_desc, blob_size, blob_size ? blob.data() : nullptr);
if (st != dnnl_success || !from_blob) { FUZZ_BAIL(); }
// Output both primitives and the PD. Downstream code must destroy both primitives.
dnnl_primitive_t *seed_primitive = &seed;
dnnl_primitive_t *primitive_from_blob = &from_blob;

// First query required size only.
size_t sz = 0;
dnnl_status_t st = dnnl_primitive_get_cache_blob(*primitive, &sz, nullptr);
if (st != dnnl_success) { FUZZ_BAIL(); }
// Cap allocations to stay under fuzzer budget; if small, retrieve the blob.
if (sz > 0 && sz <= 2048) {
    std::vector<uint8_t> buf(sz);
    size_t cap = sz;
    st = dnnl_primitive_get_cache_blob(*primitive, &cap, buf.data());
    if (st != dnnl_success) { FUZZ_BAIL(); }
}
// Return the primitive; no new persistent objects created.

// Destroy the primitive (NULL is a no-op by convention).
(void)dnnl_primitive_destroy(*primitive);
// After this call, primitive must not be used again.

// Create an attribute handle with default values.
dnnl_primitive_attr_t created = nullptr;
dnnl_status_t st = dnnl_primitive_attr_create(&created);
if (st != dnnl_success || !created) { FUZZ_BAIL(); }
// Expose the created handle via output pointer.
dnnl_primitive_attr_t *attr = &created;

// Clone the given attributes; the clone must be destroyed by the caller later.
dnnl_primitive_attr_t cloned = nullptr;
dnnl_status_t st = dnnl_primitive_attr_clone(&cloned, *existing_attr);
if (st != dnnl_success || !cloned) { FUZZ_BAIL(); }
// Output both original (mutable) and cloned attributes.
dnnl_primitive_attr_t *attr = &cloned;

// Destroy the attributes handle (NULL allowed as no-op).
(void)dnnl_primitive_attr_destroy(*attr);
// After this call, attr must not be used again.

// Set the dropout attribute using the provided memory descriptor pointer.
// The provided MD must be valid.
dnnl_status_t st = dnnl_primitive_attr_set_dropout(*attr, *dropout_desc);
if (st != dnnl_success) { FUZZ_BAIL(); }
// Return both handles; dropout_desc is an input-owned pointer and must remain valid externally.

// Query the current fpmath mode.
dnnl_fpmath_mode_t mode = dnnl_fpmath_mode_strict;
dnnl_status_t st = dnnl_primitive_attr_get_fpmath_mode(*attr, &mode);
if (st != dnnl_success) { FUZZ_BAIL(); }
(void)mode;

// Pick a random valid fpmath mode from the enumeration domain.
unsigned pick = (*FUZZ_PARAM(unsigned int)) % 5; // 5 known modes
static const dnnl_fpmath_mode_t modes[5] = {
    dnnl_fpmath_mode_strict,
    dnnl_fpmath_mode_bf16,
    dnnl_fpmath_mode_f16,
    dnnl_fpmath_mode_tf32,
    dnnl_fpmath_mode_any
};
dnnl_fpmath_mode_t mode = modes[pick];
dnnl_status_t st = dnnl_primitive_attr_set_fpmath_mode(*attr, mode);
if (st != dnnl_success) { FUZZ_BAIL(); }
// Return the mutated attributes handle.

// Query the fpmath mode and whether it applies to integer ops.
dnnl_fpmath_mode_t mode = dnnl_fpmath_mode_strict;
int apply_to_int = 0;
dnnl_status_t st = dnnl_primitive_attr_get_fpmath_mode_v2(*attr, &mode, &apply_to_int);
if (st != dnnl_success) { FUZZ_BAIL(); }
(void)mode; (void)apply_to_int;

// Get a const attribute handle owned by the primitive descriptor, then clone it to produce an owned, persistent attr.
const_dnnl_primitive_attr_t const_attr = nullptr;
dnnl_status_t st = dnnl_primitive_desc_get_attr(*primitive_desc, &const_attr);
if (st != dnnl_success || !const_attr) { FUZZ_BAIL(); }
// Clone to obtain an owned mutable attributes handle we can persist.
dnnl_primitive_attr_t cloned = nullptr;
st = dnnl_primitive_attr_clone(&cloned, const_attr);
if (st != dnnl_success || !cloned) { FUZZ_BAIL(); }
// Output the cloned attribute handle, keeping the PD alive as well.
dnnl_primitive_attr_t *attr = &cloned;
// Validation: attr is a standalone handle with its own lifetime; do not destroy here.

// Query a const memory descriptor pointer from the PD, then clone it to make an owned copy.
const_dnnl_memory_desc_t md = dnnl_primitive_desc_query_md(*primitive_desc, dnnl_query_src_md, 0);
const_dnnl_memory_desc_t chosen = md ? md : dnnl_primitive_desc_query_md(*primitive_desc, dnnl_query_dst_md, 0);
if (!chosen) { FUZZ_BAIL(); }
// Clone into an owned memory_desc handle so the fuzzer can persist it.
dnnl_memory_desc_t cloned_md = nullptr;
dnnl_status_t st = dnnl_memory_desc_clone(&cloned_md, chosen);
if (st != dnnl_success || !cloned_md) { FUZZ_BAIL(); }
// Output both PD (owner of the const MD) and the cloned MD (owned by caller).
dnnl_memory_desc_t *memory_desc = &cloned_md;
// Validation: cloned_md must be destroyed by a matching destroy stub later.

// Get the const primitive descriptor owned by the primitive and clone it to create an owned PD handle.
const_dnnl_primitive_desc_t const_pd = nullptr;
dnnl_status_t st = dnnl_primitive_get_primitive_desc(*primitive, &const_pd);
if (st != dnnl_success || !const_pd) { FUZZ_BAIL(); }
// Clone PD to get a standalone, destroyable handle.
dnnl_primitive_desc_t cloned_pd = nullptr;
st = dnnl_primitive_desc_clone(&cloned_pd, const_pd);
if (st != dnnl_success || !cloned_pd) { FUZZ_BAIL(); }
// Output the primitive (owner) and the cloned PD.
dnnl_primitive_desc_t *primitive_desc = &cloned_pd;
// Validation: cloned PD must be destroyed later by dnnl_primitive_desc_destroy.

// Get dropout attribute as a const memory desc owned by attr; then clone to obtain an owned handle.
const_dnnl_memory_desc_t const_md = nullptr;
dnnl_status_t st = dnnl_primitive_attr_get_dropout(*attr, &const_md);
if (st != dnnl_success || !const_md) { FUZZ_BAIL(); }
// Clone to owned memory_desc so the fuzzer can persist and mutate independently.
dnnl_memory_desc_t cloned_md = nullptr;
st = dnnl_memory_desc_clone(&cloned_md, const_md);
if (st != dnnl_success || !cloned_md) { FUZZ_BAIL(); }
// Output both handles.
dnnl_memory_desc_t *dropout_desc = &cloned_md;

// Choose valid fpmath mode and a boolean flag for apply_to_int.
unsigned pick = (*FUZZ_PARAM(unsigned int)) % 5; // 5 known modes
static const dnnl_fpmath_mode_t modes[5] = {
    dnnl_fpmath_mode_strict,
    dnnl_fpmath_mode_bf16,
    dnnl_fpmath_mode_f16,
    dnnl_fpmath_mode_tf32,
    dnnl_fpmath_mode_any
};
dnnl_fpmath_mode_t mode = modes[pick];
int apply_to_int = (int)((*FUZZ_PARAM(unsigned int)) & 1u);
dnnl_status_t st = dnnl_primitive_attr_set_fpmath_mode_v2(*attr, mode, apply_to_int);
if (st != dnnl_success) { FUZZ_BAIL(); }
// Return mutated attr.

// Query deterministic flag.
int deterministic = 0;
dnnl_status_t st = dnnl_primitive_attr_get_deterministic(*attr, &deterministic);
if (st != dnnl_success) { FUZZ_BAIL(); }
(void)deterministic;

// Toggle deterministic attribute using a boolean flag.
int value = (int)((*FUZZ_PARAM(unsigned int)) & 1u);
dnnl_status_t st = dnnl_primitive_attr_set_deterministic(*attr, value);
if (st != dnnl_success) { FUZZ_BAIL(); }

// Query accumulation mode.
dnnl_accumulation_mode_t mode = dnnl_accumulation_mode_strict;
dnnl_status_t st = dnnl_primitive_attr_get_accumulation_mode(*attr, &mode);
if (st != dnnl_success) { FUZZ_BAIL(); }
(void)mode;

// Pick a valid accumulation mode.
unsigned pick = (*FUZZ_PARAM(unsigned int)) % 6; // 6 known modes
static const dnnl_accumulation_mode_t modes[6] = {
    dnnl_accumulation_mode_strict,
    dnnl_accumulation_mode_relaxed,
    dnnl_accumulation_mode_any,
    dnnl_accumulation_mode_s32,
    dnnl_accumulation_mode_f32,
    dnnl_accumulation_mode_f16
};
dnnl_status_t st = dnnl_primitive_attr_set_accumulation_mode(*attr, modes[pick]);
if (st != dnnl_success) { FUZZ_BAIL(); }

