dnnl_rounding_mode_t mode = pick ? dnnl_rounding_mode_stochastic : dnnl_rounding_mode_environment;
dnnl_status_t st = dnnl_primitive_attr_set_rounding(*attr, arg, mode);
if (st != dnnl_success) { FUZZ_BAIL(); }

