dnnl_status_t st = dnnl_primitive_attr_set_scales(*attr, arg, mask, group_ndims, group_dims, dt);
if (st != dnnl_success) { FUZZ_BAIL(); }
// Validation: uses empty grouping (ndims=0, dims=NULL) and a valid datatype; attr remains alive for reuse.

