int arg = 1; int mask = 0; int ndims = 0;
const dnnl_dim_t *group_dims = nullptr; // allowed because ndims==0
dnnl_data_type_t dt = dnnl_f32;
int is_on_host = (int)((*FUZZ_PARAM(unsigned int)) & 1u);
dnnl_status_t st = dnnl_primitive_attr_set_scales_v2(*attr, arg, mask, ndims, group_dims, dt, is_on_host);
if (st != dnnl_success) { FUZZ_BAIL(); }
// Validation: passes NULL dims with ndims=0 and a valid flag/datatype; attr persists.

