// Construct a concrete implementation of the abstract threadpool interface.
// Supports both synchronous and simulated asynchronous modes (no real threads).
class FuzzThreadpool final : public dnnl::threadpool_interop::threadpool_iface {
public:
    FuzzThreadpool(int nthreads, bool async)
        : nthreads_(nthreads > 0 ? nthreads : 1)
        , in_parallel_(false)
        , flags_(async ? static_cast<uint64_t>(1) : static_cast<uint64_t>(0)) {}

    int get_num_threads() const override { return nthreads_; }

    bool get_in_parallel() const override { return in_parallel_; }

    void parallel_for(int n, const std::function<void(int, int)> &fn) override {
        // Enforce API requirement: n must be non-negative.
        if (n < 0) { FUZZ_BAIL(); }
        if ((flags_ & 1ull) != 0ull) {
            // ASYNCHRONOUS: store work and return immediately.
            pending_.emplace_back(n, fn);
        } else {
            // Synchronous: execute immediately on caller thread.
            in_parallel_ = true;
            for (int i = 0; i < n; ++i) { fn(i, n); }
            in_parallel_ = false;
        }
    }

    uint64_t get_flags() const override { return flags_; }

    void wait() override {
        // Execute any queued work from asynchronous submissions.
        if (pending_.empty()) return;
        in_parallel_ = true;
        for (auto &job : pending_) {
            const int n = job.first;
            auto &fn = job.second;
            for (int i = 0; i < n; ++i) { fn(i, n); }
        }
        in_parallel_ = false;
        pending_.clear();
    }

private:
    int nthreads_;
    mutable bool in_parallel_;
    uint64_t flags_; // bit 0 == ASYNCHRONOUS
    std::vector<std::pair<int, std::function<void(int,int)>>> pending_;
};

